  if(!items.length)return undefined;return {unit:units,view:items.some(i=>i.start[2]||i.end[2])?'iso':'xy',items,note:units==='m'?'Geometry uses metres. Force arrows show direction only.':'Force uses newtons. Axis reference arrows show direction only.'};
